const views=document.querySelectorAll('.view'),nav=document.querySelectorAll('.nav-link');
nav.forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
function showView(id){nav.forEach(x=>x.classList.toggle('active',x.dataset.view===id));views.forEach(x=>x.classList.toggle('active-view',x.id===id));if(id==='explore')renderQuestions(1);window.scrollTo({top:0,behavior:'smooth'})}
const store={get(k,f=null){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){localStorage.setItem(k,JSON.stringify(v))}},makeUid=()=>crypto.randomUUID?.()||`cg_${Date.now()}_${Math.random().toString(36).slice(2)}`,escapeHtml=s=>s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const participantUid=store.get('cg_uid')||makeUid();store.set('cg_uid',participantUid);

const gate=document.getElementById('gate'),termsStep=document.getElementById('termsStep'),profileStep=document.getElementById('profileStep'),termsConsent=document.getElementById('termsConsent'),continueTerms=document.getElementById('continueTerms');
termsConsent.addEventListener('change',()=>continueTerms.disabled=!termsConsent.checked);continueTerms.addEventListener('click',()=>{termsStep.classList.add('hidden');profileStep.classList.remove('hidden')});
async function buildDemographics(){const target=document.getElementById('demographicFields'),saved=store.get('cg_profile',{});try{const schema=await fetch('metadata/demographics.schema.json').then(r=>r.json());target.innerHTML=schema.fields.map(f=>`<label>${f.label}<select name="${f.id}" ${f.required?'required':''}>${f.options.map(o=>`<option ${saved[f.id]===o?'selected':''}>${o}</option>`).join('')}</select><span class="field-note">${f.note}</span></label>`).join('')}catch{target.innerHTML='<p>Context fields are unavailable. You can continue without them.</p>'}}buildDemographics();
function profileSummary(profile=store.get('cg_profile',{})){const values=Object.values(profile).filter(v=>v&&!/^prefer not/i.test(v));document.getElementById('contextSummary').innerHTML=`${values.slice(0,3).map(v=>`<span class="chip selected">${escapeHtml(v)}</span>`).join('')}<button class="chip add" id="addContext">＋ Add / edit context</button>`;document.getElementById('addContext').addEventListener('click',openProfile);document.getElementById('profileMark').textContent=values[0]?.slice(0,2).toUpperCase()||'CG';document.getElementById('profileLabel').textContent=values[0]||'My context'}
function enterApp(profile={}){store.set('cg_profile',profile);profileSummary(profile);gate.classList.add('hidden')}
document.getElementById('profileForm').addEventListener('submit',e=>{e.preventDefault();enterApp(Object.fromEntries(new FormData(e.currentTarget)))});document.getElementById('skipProfile').addEventListener('click',()=>enterApp(store.get('cg_profile',{})));
function openProfile(){termsStep.classList.add('hidden');profileStep.classList.remove('hidden');gate.classList.remove('hidden');buildDemographics()}profileSummary();

const profanityPattern=/\b(?:fuck|shit|bitch|cunt|asshole|bastard)\w*\b/i;
const maliciousPattern=/\b(?:build|make|create|write|plan|help|teach|instructions?)\b.{0,45}\b(?:bomb|weapon|malware|ransomware|poison|doxx|kidnap|explosive|phishing|steal|attack|kill|harm)\b|\b(?:how (?:can|do) i|i want to|ways? to)\b.{0,55}\b(?:attack|kill|harm|poison|doxx|kidnap|steal|phish)\b|\b(?:evade|bypass)\b.{0,30}\b(?:security|moderation|police|detection)\b/i;
const piiPattern=/\b[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}\b|\b(?:\+?1[-.\s]?)?(?:\(?\d{3}\)?[-.\s]?)\d{3}[-.\s]?\d{4}\b|\b\d{3}-\d{2}-\d{4}\b/i;
function screenText(text,{allowPii=false}={}){if(!text.trim())return{ok:false,reason:'empty'};if(profanityPattern.test(text))return{ok:false,reason:'vulgar'};if(maliciousPattern.test(text))return{ok:false,reason:'malicious'};if(!allowPii&&piiPattern.test(text))return{ok:false,reason:'pii'};return{ok:true}}
const safetyDialog=document.getElementById('safetyDialog');document.querySelectorAll('.safety-close').forEach(b=>b.addEventListener('click',()=>safetyDialog.close()));function refuse(reason){document.getElementById('safetyReason').textContent=reason==='vulgar'?'Vulgar or abusive language was detected. Rewrite the request respectfully.':reason==='pii'?'Possible identifying information was detected. Remove it before continuing.':'Words, intent, or purpose associated with harmful or malicious activity were detected. Reframe the question toward prevention, safety, recovery, or public benefit.';safetyDialog.showModal()}

const question=document.getElementById('question'),count=document.getElementById('count');question.addEventListener('input',()=>{count.textContent=`${question.value.length} / 500`;count.classList.remove('input-alert')});
function cappedTags(containerId,countId){const box=document.getElementById(containerId),label=document.getElementById(countId);if(!box)return()=>[];const buttons=[...box.querySelectorAll('button')],selected=()=>buttons.filter(x=>x.classList.contains('selected')).map(x=>x.dataset.tag);buttons.forEach(b=>{b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{if(b.classList.contains('selected'))b.classList.remove('selected');else if(selected().length<5)b.classList.add('selected');b.setAttribute('aria-pressed',String(b.classList.contains('selected')));const n=selected().length;label.textContent=containerId==='filterTags'?`${n} / 5`:`${n} AI-suggested · click to review`;buttons.forEach(x=>x.disabled=n>=5&&!x.classList.contains('selected'));if(containerId==='filterTags')renderQuestions(1)})});return selected}
const getAskTags=cappedTags('askTags','tagCount'),getFilterTags=cappedTags('filterTags','filterCount');
const tagRules={Home:/home|house|repair|rent|property|household/i,Costs:/cost|money|budget|afford|price|expense/i,Community:/community|neighbor|people|local|together|public/i,Work:/work|job|shift|career|employee/i,Wellbeing:/health|stress|wellbeing|care|older|cooling/i,Education:/school|learn|teach|education|student|skill/i,Environment:/climate|heat|water|energy|environment|weather/i};
function suggestTags(text){document.querySelectorAll('#askTags button.selected').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});const matched=Object.entries(tagRules).filter(([,rule])=>rule.test(text)).slice(0,5).map(([tag])=>tag);if(!matched.length)matched.push('Community');matched.forEach(tag=>document.querySelector(`#askTags [data-tag="${tag}"]`)?.click());return matched}
question.addEventListener('blur',()=>suggestTags(question.value));

const dialog=document.getElementById('answerDialog');document.getElementById('askBtn').addEventListener('click',()=>{const text=question.value.trim();if(!text||!document.getElementById('humanityIntent').checked){count.textContent='Add a question and confirm the humanity-benefit intent.';count.classList.add('input-alert');return}const screened=screenText(text);if(!screened.ok){refuse(screened.reason);return}const tags=getAskTags().length?getAskTags():suggestTags(text),record={id:makeUid(),participant_uid:participantUid,profile:store.get('cg_profile',{}),question:text,tags,created_at:new Date().toISOString(),prototype_only:true};store.set('cg_questions',[...store.get('cg_questions',[]),record].slice(-25));dialog.dataset.questionId=record.id;document.getElementById('echoQuestion').textContent=text;dialog.showModal()});
document.querySelector('#answerDialog .close').addEventListener('click',()=>dialog.close());function saveReaction(position,reason=''){store.set('cg_reactions',[...store.get('cg_reactions',[]),{question_id:dialog.dataset.questionId,participant_uid:participantUid,position,reason,created_at:new Date().toISOString()}].slice(-50))}
document.querySelectorAll('#answerDialog [data-rate]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#answerDialog [data-rate]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');if(b.dataset.rate==='no'){document.getElementById('thanks').classList.add('hidden');document.getElementById('feedback').classList.remove('hidden')}else{document.getElementById('feedback').classList.add('hidden');document.getElementById('thanks').classList.remove('hidden');saveReaction(b.dataset.rate)}}));
document.getElementById('submitFeedback').addEventListener('click',()=>{const field=document.getElementById('why'),text=field.value.trim(),screened=screenText(text,{allowPii:false});if(screened.reason==='empty'){field.setCustomValidity('Please explain what should change.');field.reportValidity();return}field.setCustomValidity('');if(!screened.ok){refuse(screened.reason);return}saveReaction('disagree',text);document.getElementById('feedback').classList.add('hidden');document.getElementById('thanks').classList.remove('hidden')});document.getElementById('followQuestion').addEventListener('click',e=>{e.currentTarget.textContent='✓ Following';store.set('cg_following',true)});document.getElementById('favoriteQuestion').addEventListener('click',e=>{e.currentTarget.textContent='♥ Favorited';store.set('cg_favorite',true)});document.getElementById('askAnother').addEventListener('click',()=>{dialog.close();question.value='';question.focus();count.textContent='0 / 500';document.getElementById('humanityIntent').checked=false;document.querySelectorAll('#askTags button.selected').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')})});

const questions=[
{id:'q1',title:'How can neighbors share the cost of emergency home repairs without creating conflict?',tags:['Home','Costs','Community'],useful:84,voices:326,answer:'Use a written, opt-in repair circle with a small contribution cap, transparent records, and a hardship exception reviewed by more than one member.'},
{id:'q2',title:'What is a fair way for shift workers to swap schedules at short notice?',tags:['Work','Community'],useful:71,voices:184,answer:'Use a published swap window, equal eligibility, manager confirmation only for coverage, and an appeal path that does not penalize caregivers.'},
{id:'q3',title:'How do we make a local cooling center usable for older residents?',tags:['Community','Wellbeing','Environment'],useful:91,voices:508,answer:'Design around transportation, extended hours, medication storage, accessibility, and trusted neighborhood outreach—not only the building.'},
{id:'q4',title:'What is a practical way to teach household budgeting to teenagers?',tags:['Education','Costs','Home'],useful:68,voices:92,answer:'Use a four-week simulation based on real tradeoffs, privacy-safe local prices, reflection, and the ability to revise decisions.'},
{id:'q5',title:'How can a small community prepare for extended power outages?',tags:['Community','Environment','Home'],useful:82,voices:211,answer:'Map medically essential needs first, then shared charging, food safety, communication, and neighbor check-in procedures.'},
{id:'q6',title:'How should a team document knowledge when experienced workers leave?',tags:['Work','Education'],useful:77,voices:139,answer:'Pair task walkthroughs with decision logs, failure examples, and scheduled practice by the next owner.'},
{id:'q7',title:'How can renters reduce home energy costs without major renovations?',tags:['Home','Costs','Environment'],useful:74,voices:167,answer:'Start with landlord-safe sealing, appliance measurement, thermostat routines, and utility assistance before purchasing equipment.'},
{id:'q8',title:'What makes a neighborhood skill-sharing program fair and useful?',tags:['Community','Education','Work'],useful:79,voices:245,answer:'Publish needs and offers, value different kinds of labor, provide accessibility support, and rotate coordination responsibilities.'},
{id:'q9',title:'How can caregivers coordinate appointments without sharing private records?',tags:['Wellbeing','Community'],useful:86,voices:301,answer:'Share only schedules, responsibilities, and consent states; keep medical details with the person and authorized providers.'},
{id:'q10',title:'How can schools help families understand AI-generated information?',tags:['Education','Community'],useful:88,voices:356,answer:'Teach source checking, uncertainty, comparison, and respectful challenge through familiar community examples.'}
];
const search=document.getElementById('searchQuestions'),questionList=document.getElementById('questionList'),pagination=document.getElementById('pagination'),pageSize=4;let currentMatches=[];
function tokens(s){return s.toLowerCase().match(/[a-z0-9]+/g)||[]}function matchesDictionary(item,query){const needles=tokens(query),haystack=new Set(tokens(`${item.title} ${item.tags.join(' ')}`));return needles.every(word=>[...haystack].some(term=>term.startsWith(word)))}
function allQuestions(){const local=store.get('cg_questions',[]).map(q=>({id:q.id,title:q.question,tags:q.tags,useful:0,voices:1,answer:'This locally saved prototype question uses the illustrative three-tier answer shown when it was created.',local:true}));return[...local.reverse(),...questions]}
function renderQuestions(page=1){const query=(search?.value||'').trim(),tags=getFilterTags();currentMatches=allQuestions().filter(q=>(!query||matchesDictionary(q,query))&&(!tags.length||tags.every(t=>q.tags.includes(t))));const pages=Math.max(1,Math.ceil(currentMatches.length/pageSize)),safePage=Math.min(page,pages),items=currentMatches.slice((safePage-1)*pageSize,safePage*pageSize);document.getElementById('resultCount').textContent=`${currentMatches.length} question${currentMatches.length===1?'':'s'}`;questionList.innerHTML=items.length?items.map(q=>`<article><div>${q.tags.map(t=>`<span class="tag"># ${escapeHtml(t)}</span>`).join('')}<span class="tag-ai-note">${q.local?'Saved in this browser':'AI tagged'}</span></div><h3>${escapeHtml(q.title)}</h3><footer><b>${q.local?'Awaiting community review':`${q.useful}% useful`}</b><span>${q.voices} voice${q.voices===1?'':'s'}</span><span class="comment-count">${(store.get(`cg_comments_${q.id}`,[])).length} comments</span><div class="card-actions"><button data-open="${q.id}">Rate</button><button data-open="${q.id}">Open thread →</button></div></footer></article>`).join(''):'<p class="empty-state">No question matches every word and selected tag. Try fewer terms or begin a new seed.</p>';pagination.innerHTML=pages>1?Array.from({length:pages},(_,i)=>`<button class="${i+1===safePage?'active':''}" aria-label="Page ${i+1}" aria-current="${i+1===safePage?'page':'false'}" data-page="${i+1}">${i+1}</button>`).join(''):'';questionList.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openThread(b.dataset.open)));pagination.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>renderQuestions(Number(b.dataset.page))))}
search.addEventListener('input',()=>renderQuestions(1));document.getElementById('clearSearch').addEventListener('click',()=>{search.value='';document.querySelectorAll('#filterTags button.selected').forEach(x=>x.click());renderQuestions(1)});renderQuestions();

const threadDialog=document.getElementById('threadDialog');document.querySelector('.thread-close').addEventListener('click',()=>threadDialog.close());function openThread(id){const q=allQuestions().find(x=>x.id===id);if(!q)return;threadDialog.dataset.questionId=id;document.getElementById('threadTitle').textContent=q.title;document.getElementById('threadTags').innerHTML=q.tags.map(t=>`<span class="tag"># ${escapeHtml(t)}</span>`).join('');document.getElementById('threadAnswer').textContent=q.answer;document.getElementById('commentInput').value='';document.getElementById('commentMessage').textContent='Strict language and intent screening applies.';renderComments(id);threadDialog.showModal()}
function renderComments(id){const list=document.getElementById('commentList'),comments=store.get(`cg_comments_${id}`,[]);list.innerHTML=comments.length?'':'<p class="comment">No comments yet. Add useful context or respectful disagreement.</p>';comments.forEach(c=>{const div=document.createElement('div');div.className='comment';div.textContent=c.text;const small=document.createElement('small');small.textContent=`Anonymous participant · ${new Date(c.created_at).toLocaleDateString()}`;div.appendChild(small);list.appendChild(div)})}
document.querySelectorAll('[data-thread-rate]').forEach(b=>b.addEventListener('click',()=>{store.set('cg_thread_ratings',[...store.get('cg_thread_ratings',[]),{question_id:threadDialog.dataset.questionId,rating:b.dataset.threadRate,uid:participantUid}]);document.querySelectorAll('[data-thread-rate]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen')}));
document.getElementById('postComment').addEventListener('click',()=>{const input=document.getElementById('commentInput'),message=document.getElementById('commentMessage'),screened=screenText(input.value);if(!screened.ok){message.textContent=screened.reason==='vulgar'?'Comment blocked: vulgar or abusive language detected.':screened.reason==='pii'?'Comment blocked: possible identifying information detected.':'Comment blocked: harmful or malicious intent detected.';message.classList.add('blocked');return}const key=`cg_comments_${threadDialog.dataset.questionId}`;store.set(key,[...store.get(key,[]),{text:input.value.trim(),uid:participantUid,created_at:new Date().toISOString()}]);input.value='';message.textContent='Comment added to this browser.';message.classList.remove('blocked');renderComments(threadDialog.dataset.questionId);renderQuestions()});
document.querySelectorAll('.knowledge-level button').forEach(n=>n.addEventListener('click',()=>document.getElementById('treeNote').textContent=`${n.textContent} — ${n.dataset.note}`));
const dataDialog=document.getElementById('dataDialog');document.getElementById('openDataPanel').addEventListener('click',()=>dataDialog.showModal());document.querySelector('.data-close').addEventListener('click',()=>dataDialog.close());document.getElementById('editProfile').addEventListener('click',()=>{dataDialog.close();openProfile()});document.getElementById('clearLocalData').addEventListener('click',()=>{if(confirm('Clear this prototype profile, questions, comments, reactions, follows, and browser ID? This cannot be undone.')){Object.keys(localStorage).filter(k=>k.startsWith('cg_')).forEach(k=>localStorage.removeItem(k));location.reload()}});
